<script lang="ts">
  import { onMount } from 'svelte';

  let dismissing = $state(false);
  let gone = $state(false);

  onMount(() => {
    // Hold until `load` (waits for the hero image so it never pops in), but cap
    // it so slow below-the-fold CMS images can't keep the curtain up forever.
    const MIN = 700;
    const MAX = 2600;
    const start = performance.now();
    let dismissed = false;
    let t1 = 0;
    let t2 = 0;
    const dismiss = () => {
      if (dismissed) return;
      dismissed = true;
      const wait = Math.max(0, MIN - (performance.now() - start));
      t1 = window.setTimeout(() => {
        dismissing = true;
        t2 = window.setTimeout(() => (gone = true), 650);
      }, wait);
    };
    if (document.readyState === 'complete') dismiss();
    else window.addEventListener('load', dismiss, { once: true });
    const cap = window.setTimeout(dismiss, MAX);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(cap);
      window.removeEventListener('load', dismiss);
    };
  });
</script>

