<style>
  .preloader {
    position: fixed;
    inset: 0;
    z-index: 200;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: var(--paper);
    transition: opacity 0.6s ease;
  }

  .preloader.is-out {
    opacity: 0;
    pointer-events: none;
  }

  /* Full-screen skeleton shimmer — a soft light band sweeping across, a backup
     "loading" cue behind the pulsing glyph. */
  .preloader::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
      100deg,
      transparent 35%,
      rgba(26, 26, 26, 0.035) 50%,
      transparent 65%
    );
    background-size: 220% 100%;
    animation: preloader-shimmer 1.8s ease-in-out infinite;
  }

  .preloader-glyph {
    position: relative;
    width: clamp(72px, 11vw, 124px);
    height: auto;
    animation: preloader-pulse 1.5s ease-in-out infinite;
  }

  .preloader-glyph path {
    fill: var(--ink);
  }

  @keyframes preloader-pulse {
    0%,
    100% {
      transform: scale(0.9);
      opacity: 0.4;
    }

    50% {
      transform: scale(1.08);
      opacity: 1;
    }
  }

  @keyframes preloader-shimmer {
    0% {
      background-position: 160% 0;
    }

    100% {
      background-position: -60% 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .preloader-glyph {
      animation: none;
      opacity: 0.85;
    }

    .preloader::before {
      animation: none;
    }
  }
</style>
